.breadcrumb-list {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-1);
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: var(--font-sm);
}

.breadcrumb-item {
  display: inline-flex;
  align-items: center;
}

.breadcrumb-link {
  padding: var(--space-1) var(--space-2);
  border: none;
  /* The family's radius, not a smaller one of its own: every pressable thing in
   * this system is a full-radius pill, and a breadcrumb crumb that rounds at 4px
   * is the one control that does not look like the rest (owner, 2026-08-29). */
  border-radius: var(--radius-full);
  background: transparent;
  /* --link-quiet: a breadcrumb is a link in chrome. See the LINKS block in
   * semantic.css — one decision for what a link is coloured, four hand-picked
   * answers before it. */
  color: var(--link-quiet);
  font: inherit;
  text-decoration: none;
  cursor: pointer;
  transition: color var(--duration-fast), background var(--duration-fast);
}
/* Pressed: one stop past hover, the third answer every control now gives. */
.breadcrumb-link:active { color: var(--link-hover); }
.breadcrumb-link:hover {
  color: var(--foreground);
  background: var(--accent-soft);
}

.breadcrumb-current {
  padding: var(--space-1) var(--space-2);
  color: var(--foreground);
  font-weight: var(--font-weight-medium);
}

.breadcrumb-sep {
  display: inline-flex;
  align-items: center;
  color: var(--icon-muted);
}

import './Breadcrumb.css'
import { Fragment, type ReactNode } from 'react'
import { cn } from '../lib/cn'
import { Icon } from '../Icon'

export type Crumb = {
  label: string
  /** Anchor href, or omit for an onSelect button. The LAST crumb ignores both
   *  and renders as plain current-page text. */
  href?: string
  onSelect?: () => void
}

type Props = {
  items: Crumb[]
  /** Accessible name for the nav landmark. Default "Breadcrumb". */
  label?: string
  className?: string
}

/* The trail back up a record hierarchy, e.g. Library / Reports / Q3. Routing
 * agnostic: pass `href` for anchors, `onSelect` for buttons. The last item is
 * always the current page (aria-current), not a link. Replaces the old habit of
 * faking a breadcrumb with a subtitle string. 
   *
   * Copy: each crumb is the page's own title, unshortened. A trail that renames
   * its steps is a trail the reader cannot match to where they have been.
   */
export function Breadcrumb({ items, label = 'Breadcrumb', className }: Props) {
  return (
    <nav className={cn('breadcrumb', className)} aria-label={label}>
      <ol className="breadcrumb-list">
        {items.map((item, i) => {
          const last = i === items.length - 1
          let content: ReactNode
          if (last) content = <span className="breadcrumb-current" aria-current="page">{item.label}</span>
          else if (item.href) content = <a className="breadcrumb-link" href={item.href}>{item.label}</a>
          else content = <button type="button" className="breadcrumb-link" onClick={item.onSelect}>{item.label}</button>

          return (
            <Fragment key={item.label}>
              <li className="breadcrumb-item">{content}</li>
              {!last && <li className="breadcrumb-sep" aria-hidden="true"><Icon name="chevron_right" /></li>}
            </Fragment>
          )
        })}
      </ol>
    </nav>
  )
}
